"""
    Transforms [v1,v2] and returns it
    such that it is in the same order
    and has the same middle interval as [gm1, gm2]
    """
def switchAndTranslate(
    gm1: Any, gm2: Any, v1: Any, v2: Any, wrapModulo: Any
) -> object {
    assert (v1 < v2);
    if wrapModulo {
        gmMiddle = float((gm1 + gm2)) / 2.0;
        half = float((v2 - v1)) / 2.0;
        v1 = gmMiddle - half;
        v2 = gmMiddle + half;
    }
    if (((gm1 - gm2) * (v1 - v2)) < 0) {
        (v1, v2) = (v2, v1);
    }
    return [v1, v2];
}

"""Remove duplicate letters on either end, if the are adjacent.

    Args:
        words (list): The list of words

    Returns:
        list: An updated word list with duplicate ends removed for each word.
    """
def chop_duplicate_ends(word: Any) -> object {
    if (word[0] == word[1]) {
        word = word[1:];
    }
    if (word[-2:-1] == word[-1:]) {
        word = word[:-1];
    }
    return word;
}

