    hist: map from word to frequency

    returns: list of (frequency, word) pairs
    """
def most_common(hist: Any) -> object {
    t = [];
    for (key, value) in hist.items() {
        t.append((value, key));
    }
    t.sort();
    t.reverse();
    return t;
}

"""Interpolate from pale grey to deep red-orange.

    Boundaries:

        min, 0.0: #cccccc = (204, 204, 204)
        max, 1.0: #ff2000 = (255, 32, 0)
    """
def intensity2color(scale: Any) -> object {
    assert (0.0 <= scale <= 1.0);
    baseline = 204;
    max_rgb = (255, 32, 0);
    new_rbg = `tuple(
        (baseline + int(round((scale * (component - baseline)))))
        for component in max_rgb
    );
    return new_rbg;
}

